"use client";

// The public course catalog behind /programs, /pricing and /about.
//
// Live data comes from GET /courses/catalog, which reads the same rows
// /admin/courses manages — so every program, course and lesson count on the
// site follows the catalog as it grows. catalog-snapshot.json (generated by
// `npm run export:public-catalog` in server/) is what renders instantly and
// whenever the API is unreachable (e.g. a cold start), so these pages are
// never blank. The live response always replaces it once it arrives.

import { useEffect, useState } from "react";
import snapshot from "./catalog-snapshot.json";

export type LessonType = "LEARNING" | "COURSE_TEST" | "STAGE_TEST" | "FINAL_TEST";

export interface CatalogLesson {
  order: number;
  title: string;
  type: LessonType;
}

export interface CatalogModule {
  slug: string;
  title: string;
  order: number;
  /** Every session in the course, including its course test. */
  lessonCount: number;
  /** Teaching lessons only. */
  learningCount: number;
  lessons: CatalogLesson[];
}

export interface CatalogStage {
  number: number;
  modules: CatalogModule[];
  assessments: CatalogLesson[];
}

export interface CatalogCourse {
  slug: string;
  title: string;
  emoji: string | null;
  category: string;
  ageMin: number;
  ageMax: number;
  kind: "odyssey" | "specialized";
  /** The lesson total shown in /admin/courses (tests included). */
  totalLessons: number;
  learningLessons: number;
  assessmentLessons: number;
  modules: CatalogModule[];
  stages: CatalogStage[];
  closingAssessments: CatalogLesson[];
}

export interface Catalog {
  courses: CatalogCourse[];
  totals: { programs: number; courses: number };
}

export const FALLBACK_CATALOG = snapshot as unknown as Catalog;

export function findCourse(catalog: Catalog, slug: string): CatalogCourse | undefined {
  return catalog.courses.find((c) => c.slug === slug);
}

export function isCatalog(value: unknown): value is Catalog {
  const data = value as Partial<Catalog> | null;
  return (
    !!data &&
    Array.isArray(data.courses) &&
    data.courses.length > 0 &&
    !!data.totals &&
    typeof data.totals.programs === "number" &&
    typeof data.totals.courses === "number" &&
    data.courses.every(
      (c) =>
        typeof c?.slug === "string" &&
        typeof c.totalLessons === "number" &&
        Array.isArray(c.modules) &&
        Array.isArray(c.stages) &&
        Array.isArray(c.closingAssessments),
    )
  );
}

let cached: Catalog | null = null;
let inflight: Promise<Catalog | null> | null = null;

async function fetchCatalog(): Promise<Catalog | null> {
  const base = process.env.NEXT_PUBLIC_API_URL;
  if (!base) return null;
  try {
    const res = await fetch(`${base}/courses/catalog`, { headers: { Accept: "application/json" } });
    if (!res.ok) return null;
    const data: unknown = await res.json();
    return isCatalog(data) ? data : null;
  } catch {
    return null;
  }
}

/** The catalog, instantly from the snapshot and upgraded to live data. */
export function useCatalog(): { catalog: Catalog; isLive: boolean } {
  const [state, setState] = useState<{ catalog: Catalog; isLive: boolean }>(() => ({
    catalog: cached ?? FALLBACK_CATALOG,
    isLive: cached !== null,
  }));

  useEffect(() => {
    if (cached) return;
    let cancelled = false;
    inflight ??= fetchCatalog().finally(() => {
      inflight = null;
    });
    inflight.then((live) => {
      if (!live) return;
      cached = live;
      if (!cancelled) setState({ catalog: live, isLive: true });
    });
    return () => {
      cancelled = true;
    };
  }, []);

  return state;
}

/** "28" when every value matches, otherwise the range ("24–28"). Pages quote
 *  lesson and course totals through this so they cannot disagree. */
export function describeRange(values: number[]): string {
  if (values.length === 0) return "0";
  const min = Math.min(...values);
  const max = Math.max(...values);
  return min === max ? String(min) : `${min}–${max}`;
}
